{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Doxazosin, which shares the 6,7-dimethoxy-4-aminoquinazoline core and a 2-position cyclic amine, has absolute oral bioavailability of 65 ± 14% in young volunteers, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bunazosin, another 6,7-dimethoxy-4-aminoquinazoline with a 2-position cyclic amine, has absolute bioavailability of 44.1% in volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Trimazosin, a closely related 4-aminoquinazoline with 2-piperazine substitution, shows 63% oral bioavailability in healthy men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Delavirdine, which contains a methanesulfonamide and heteroaromatic amine similar to the query, has 85% oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Vismodegib, containing a sulfonamide and pyridine, has absolute oral bioavailability of 31.8% in healthy subjects, still above the 20% threshold and supportive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tariquidar, a larger dimethoxytetrahydroisoquinoline-containing P-gp inhibitor, has low oral bioavailability in humans; this is the main contradictory evidence but is less structurally transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4-amino-6,7-dimethoxyquinazoline with a 2-position cyclic amine, closely matching doxazosin, bunazosin, and trimazosin, all of which have human oral bioavailability of 44–65%. Additional sulfonamide and pyridine features are present in other high-F drugs such as delavirdine and vismodegib. The only low-F analogue, tariquidar, is less structurally related and is outweighed by the quinazoline-based evidence. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "No experimental solubility, permeability, efflux, or metabolic stability data for the query.",
    "Formulation dependence and possible saturable absorption are not characterized for the query.",
    "Morgan similarities to the supporting analogues are modest, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

